// Enhanced price calculation with animations
$('.price-type-radio').on('change', function() {
    var productId = $(this).data('product-id');
    var priceType = $(this).val();
    var isBulkBuyer = $(this).data('bulk-buyer') === 'true';

    var priceElement = $('#price-' + productId);

    // Get all price data attributes with validation
    var bulkCashPrice = parseFloat($(this).data('bulk-cash-price')) || 0;
    var bulkCheckPrice = parseFloat($(this).data('bulk-check-price')) || 0;
    var retailCashPrice = parseFloat($(this).data('retail-cash-price')) || 0;
    var retailCheckPrice = parseFloat($(this).data('retail-check-price')) || 0;

    // Determine price based on user type and payment method
    var price = 0;
    if (isBulkBuyer) {
        price = priceType === 'cash' ? bulkCashPrice : bulkCheckPrice;
    } else {
        price = priceType === 'cash' ? retailCashPrice : retailCheckPrice;
    }

    // Update price with animation
    updatePriceDisplay(productId, price, priceElement);

    // Update cart total
    updateCartTotal();
});

function updatePriceDisplay(productId, price, priceElement) {
    // Validate price
    var displayPrice = validatePrice(price);

    // Animate price change
    animatePriceChange(priceElement, displayPrice);
}

function validatePrice(price) {
    if (price > 0) {
        return formatPrice(price);
    } else {
        return 'قیمت نامشخص';
    }
}

function animatePriceChange(element, newPrice) {
    // Fade out
    element.addClass('price-fade-out');

    setTimeout(function() {
        // Update content
        element.text(newPrice);

        // Fade in
        element.removeClass('price-fade-out').addClass('price-fade-in');

        // Clean up classes
        setTimeout(function() {
            element.removeClass('price-fade-in');
        }, 300);
    }, 150);
}

