/* Price transition animations */
.product-price {
    transition: opacity 0.3s ease-in-out;
    min-height: 1.5em; /* Prevent layout shift */
}

.price-fade-out {
    opacity: 0;
}

.price-fade-in {
    opacity: 1;
}

/* Payment type button states */
.price-type-radio:checked + label {
    box-shadow: 0 0 0 0.2rem rgba(25, 135, 84, 0.25);
    border-color: #198754;
}

.price-type-radio:not(:checked) + label {
    opacity: 0.7;
}

/* Loading state for price updates */
.price-loading {
    position: relative;
}

.price-loading::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 16px;
    height: 16px;
    margin: -8px 0 0 -8px;
    border: 2px solid #f3f3f3;
    border-top: 2px solid #198754;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}
